mod models;
mod services;
mod tools;

use serde_json::{json, Value};
use tokio::io::{AsyncBufReadExt, AsyncWriteExt, BufReader};

#[tokio::main]
async fn main() -> anyhow::Result<()> {
    tracing_subscriber::fmt().with_env_filter(tracing_subscriber::EnvFilter::from_default_env()).with_writer(std::io::stderr).init();
    eprintln!("OfficeMCP Rust v1.0.0 starting on stdio");
    let stdin = tokio::io::stdin();
    let mut stdout = tokio::io::stdout();
    let mut reader = BufReader::new(stdin);
    let mut line = String::new();
    loop {
        line.clear();
        let n = reader.read_line(&mut line).await?;
        if n == 0 { break; }
        let trimmed = line.trim();
        if trimmed.is_empty() { continue; }
        let req: Value = match serde_json::from_str(trimmed) {
            Ok(v) => v,
            Err(e) => {
                eprintln!("Invalid JSON: {} - {}", e, trimmed);
                continue;
            }
        };
        // Handle batch requests (array)
        if req.is_array() {
            for item in req.as_array().unwrap() {
                if let Some(resp) = handle_request(item).await {
                    let out = serde_json::to_string(&resp)?;
                    stdout.write_all(out.as_bytes()).await?;
                    stdout.write_all(b"\n").await?;
                    stdout.flush().await?;
                }
            }
        } else {
            if let Some(resp) = handle_request(&req).await {
                let out = serde_json::to_string(&resp)?;
                stdout.write_all(out.as_bytes()).await?;
                stdout.write_all(b"\n").await?;
                stdout.flush().await?;
            }
        }
    }
    Ok(())
}

async fn handle_request(req: &Value) -> Option<Value> {
    let jsonrpc = req.get("jsonrpc").and_then(|v| v.as_str()).unwrap_or("2.0");
    let id = req.get("id").cloned();
    let method = req.get("method").and_then(|v| v.as_str()).unwrap_or("");
    let params = req.get("params").cloned().unwrap_or(json!({}));

    // Notifications have no id, we should not respond except for initialized?
    match method {
        "initialize" => {
            let result = json!({
                "protocolVersion": "2024-11-05",
                "capabilities": {
                    "tools": { "listChanged": false },
                    "resources": {},
                    "prompts": {},
                    "logging": {}
                },
                "serverInfo": { "name": "OfficeMCP", "version": "1.0.0" }
            });
            Some(json!({"jsonrpc": jsonrpc, "id": id, "result": result}))
        },
        "notifications/initialized" | "notifications/cancelled" => None,
        "ping" => Some(json!({"jsonrpc": jsonrpc, "id": id, "result": json!({})})),
        "tools/list" => {
            let tools = get_tools();
            Some(json!({"jsonrpc": jsonrpc, "id": id, "result": {"tools": tools}}))
        },
        "tools/call" => {
            let name = params.get("name").and_then(|v| v.as_str()).unwrap_or("");
            let arguments = params.get("arguments").cloned().unwrap_or(json!({}));
            let result = dispatch_tool(name, &arguments).await;
            let is_error = result.get("Success").and_then(|v| v.as_bool()).map(|b| !b).unwrap_or(false);
            // MCP CallToolResult format: {content: [{type:"text", text: json_string}], isError?: bool}
            let text = serde_json::to_string(&result).unwrap_or("{}".to_string());
            let mut resp_result = json!({
                "content": [{ "type": "text", "text": text }]
            });
            if is_error {
                resp_result["isError"] = json!(true);
            }
            Some(json!({"jsonrpc": jsonrpc, "id": id, "result": resp_result}))
        },
        "resources/list" => Some(json!({"jsonrpc": jsonrpc, "id": id, "result": {"resources": []}})),
        "prompts/list" => Some(json!({"jsonrpc": jsonrpc, "id": id, "result": {"prompts": []}})),
        "completion/complete" => Some(json!({"jsonrpc": jsonrpc, "id": id, "result": {"completion": {"values": []}}})),
        _ => {
            if id.is_some() {
                Some(json!({"jsonrpc": jsonrpc, "id": id, "error": {"code": -32601, "message": format!("Method not found: {}", method)}}))
            } else { None }
        }
    }
}

async fn dispatch_tool(name: &str, args: &Value) -> Value {
    match name {
        // Office consolidated Tier 1
        "office_create" => tools::office::handle_office_create(args),
        "office_read" => tools::office::handle_office_read(args),
        "office_write" => tools::office::handle_office_write(args),
        "office_convert" => tools::office::handle_office_convert(args),
        "office_metadata" => tools::office::handle_office_metadata(args),
        // Tier 2
        "office_add_element" => tools::office::handle_office_add_element(args),
        "office_add_header_footer" => tools::office::handle_office_add_header_footer(args),
        "office_extract" => tools::office::handle_office_extract(args),
        "office_batch" => tools::office::handle_office_batch(args),
        // Tier 3
        "office_merge" => tools::office::handle_office_merge(args),
        "office_pdf_pages" => tools::office::handle_office_pdf_pages(args),
        // PPTX
        "pptx_create" => tools::powerpoint::handle_pptx_create(args),
        "pptx_read" => tools::powerpoint::handle_pptx_read(args),
        "pptx_add_slide" => tools::powerpoint::handle_pptx_add_slide(args),
        "pptx_manage_slide" => tools::powerpoint::handle_pptx_manage_slide(args),
        "pptx_add_title" => tools::powerpoint::handle_pptx_add_title(args),
        "pptx_add_text" => tools::powerpoint::handle_pptx_add_text(args),
        "pptx_add_image" => tools::powerpoint::handle_pptx_add_image(args),
        "pptx_add_table" => tools::powerpoint::handle_pptx_add_table(args),
        "pptx_add_shape" => tools::powerpoint::handle_pptx_add_shape(args),
        "pptx_add_line" => tools::powerpoint::handle_pptx_add_line(args),
        "pptx_add_connector" => tools::powerpoint::handle_pptx_add_connector(args),
        "pptx_add_image_base64" => tools::powerpoint::handle_pptx_add_image_base64(args),
        "pptx_z_order" => tools::powerpoint::handle_pptx_z_order(args),
        "pptx_reorder_shape" => tools::powerpoint::handle_pptx_reorder_shape(args),
        "pptx_add_group" => tools::powerpoint::handle_pptx_add_group(args),
        "pptx_set_slide_size" => tools::powerpoint::handle_pptx_set_slide_size(args),
        "pptx_set_background" => tools::powerpoint::handle_pptx_set_background(args),
        "pptx_add_notes" => tools::powerpoint::handle_pptx_add_notes(args),
        "pptx_batch" => tools::powerpoint::handle_pptx_batch(args),
        // Excel
        "excel_create" => tools::excel::handle_excel_create(args),
        "excel_read" => tools::excel::handle_excel_read(args),
        "excel_get_formatting" => tools::excel::handle_excel_get_formatting(args),
        "excel_set_cells" => tools::excel::handle_excel_set_cells(args),
        "excel_formula" => tools::excel::handle_excel_formula(args),
        "excel_manage_sheet" => tools::excel::handle_excel_manage_sheet(args),
        "excel_format_cells" => tools::excel::handle_excel_format_cells(args),
        "excel_batch" => tools::excel::handle_excel_batch(args),
        // Word legacy
        "word_read" => tools::word::handle_word_read(args),
        "word_add_content" => tools::word::handle_word_add_content(args),
        "word_add_element" => tools::word::handle_word_add_element(args),
        "word_add_image" => tools::word::handle_word_add_image(args),
        "word_convert" => tools::word::handle_word_convert(args),
        "word_batch" => tools::word::handle_word_batch(args),
        _ => json!({"Success": false, "Message": format!("Unknown tool: {}", name), "Suggestion": "Use tools/list to see available tools"}),
    }
}

